import { execFile } from 'node:child_process';
import { mkdtemp, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { VideoAnalysis } from '@pseudo/shared';
import { ffmpegPath } from '../media/ffmpeg';

/** A real 3s 320x240 mp4 with a sine-tone audio track, generated by the bundled ffmpeg. */
export async function makeTestVideo(): Promise<{ path: string; data: Buffer }> {
  const dir = await mkdtemp(join(tmpdir(), 'pseudo-test-'));
  const path = join(dir, 'test.mp4');
  await new Promise<void>((resolve, reject) => {
    execFile(
      ffmpegPath(),
      [
        '-hide_banner',
        '-f',
        'lavfi',
        '-i',
        'testsrc=duration=3:size=320x240:rate=10',
        '-f',
        'lavfi',
        '-i',
        'sine=frequency=440:duration=3',
        '-pix_fmt',
        'yuv420p',
        '-shortest',
        '-y',
        path,
      ],
      (err) => (err ? reject(err) : resolve()),
    );
  });
  return { path, data: await readFile(path) };
}

